import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Chassis placed at ground level with sufficient clearance
    chassis = sandbox.add_beam(x=10.0, y=1.8, width=2.0, height=0.5, density=2.0)
    sandbox.set_material_properties(chassis, restitution=0.1, friction=0.5)

    # Left wheel with high friction for better traction
    wheel1 = sandbox.add_wheel(x=10.0 - 1.0, y=1.8, radius=0.8, density=1.0)
    sandbox.set_material_properties(wheel1, restitution=0.1, friction=1.0)
    left_joint = sandbox.add_joint(chassis, wheel1, (10.0 - 1.0, 1.8), type='pivot')

    # Right wheel with high friction for better traction
    wheel2 = sandbox.add_wheel(x=10.0 + 1.0, y=1.8, radius=0.8, density=1.0)
    sandbox.set_material_properties(wheel2, restitution=0.1, friction=1.0)
    right_joint = sandbox.add_joint(chassis, wheel2, (10.0 + 1.0, 1.8), type='pivot')

    return {"body": chassis, "joints": [left_joint, right_joint]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None

    # Differential drive: left wheel forward, right wheel backward
    if torso is not None and torso.position.x > 28.0:
        rotation_speed = 0.0
    else:
        for i, joint in enumerate(joints):
            if i == 0:
                # Left wheel: positive rotation (forward)
                sandbox.set_motor(joint, 5.0, max_torque=100.0)
            else:
                # Right wheel: negative rotation (backward)
                sandbox.set_motor(joint, -5.0, max_torque=100.0)

